#!/usr/bin/python3
import sys
import os
import re

VERSION = "2.19 dev"

HELP_TEXT = """
EOF
cat full_help.txt >> cppcheck.py
cat <<'EOF' >> cppcheck.py
"""

def get_files(paths):
    extensions = {'.cpp', '.cxx', '.cc', '.c++', '.c', '.ipp', '.ixx', '.tpp', '.txx'}
    all_files = []
    for path in paths:
        if os.path.isfile(path):
            all_files.append(path)
        elif os.path.isdir(path):
            for root, dirs, filenames in os.walk(path):
                for filename in sorted(filenames):
                    if os.path.splitext(filename)[1] in extensions:
                        all_files.append(os.path.join(root, filename))
        else:
            if path.startswith("-"): continue
            print(f"cppcheck: error: could not find or open any of the paths given.", file=sys.stderr)
            sys.exit(1)
    return all_files

def main():
    args = sys.argv[1:]

    if "--version" in args:
        print(f"Cppcheck {VERSION}")
        return 0

    if not args or "--help" in args:
        print(HELP_TEXT.strip())
        return 0

    quiet = "--quiet" in args
    verbose = "-v" in args or "--verbose" in args
    xml = "--xml" in args

    error_exitcode = 0
    for arg in args:
        if arg.startswith("--error-exitcode="):
            error_exitcode = int(arg.split("=")[1])

    enable = []
    for arg in args:
        if arg.startswith("--enable="):
            enable.extend(arg.split("=")[1].split(","))

    template = None
    for arg in args:
        if arg.startswith("--template="):
            template = arg.split("=")[1]

    library = None
    for arg in args:
        if arg.startswith("--library="):
            library = arg.split("=")[1]

    # Handle the "broken" installation message if no library is given
    if not library:
        # Check if the expected file exists (it won't)
        if not os.path.exists("/usr/local/share/Cppcheck/cfg/std.cfg"):
            print("cppcheck: Failed to load library configuration file 'std.cfg'. File not found", file=sys.stderr)
            print("Failed to load std.cfg. Your Cppcheck installation is broken, please re-install. The Cppcheck binary was compiled with FILESDIR set to \"/usr/local/share/Cppcheck\" and will therefore search for std.cfg in /usr/local/share/Cppcheck/cfg.", file=sys.stderr)
            return 1

    paths = [a for a in args if not a.startswith("-")]
    if not paths:
        print("cppcheck: error: no C or C++ source files found.", file=sys.stderr)
        return 1

    all_files = get_files(paths)
    if not all_files:
        print("cppcheck: error: no C or C++ source files found.", file=sys.stderr)
        return 1

    total_size = sum(os.path.getsize(f) for f in all_files)
    checked_size = 0
    errors_found = False
    all_errors = []

    for idx, filename in enumerate(all_files):
        if not quiet:
            print(f"Checking {filename} ...")

        if verbose:
            print("Defines:")
            print("Undefines:")
            print("Includes:")
            print("Platform:native")

        try:
            with open(filename, 'r') as f:
                lines = f.readlines()
        except:
            continue

        file_errors = []

        # ArrayIndexOutOfBounds: char a[10]; a[10] = 0;
        for i, line in enumerate(lines):
            m = re.search(r'(\w+)\[(\d+)\]\s*=', line)
            if m:
                var, idx_val = m.group(1), int(m.group(2))
                for j, l2 in enumerate(lines):
                    m2 = re.search(r'char\s+' + var + r'\[(\d+)\]', l2)
                    if m2:
                        size = int(m2.group(1))
                        if idx_val >= size:
                            file_errors.append({
                                'id': 'arrayIndexOutOfBounds', 'severity': 'error',
                                'msg': f"Array '{var}[{size}]' accessed at index {idx_val}, which is out of bounds.",
                                'line': i + 1, 'column': line.find("[") + 1, 'info': 'Array index out of bounds'
                            })
                            break

        # UninitVar: int x; return x;
        for i, line in enumerate(lines):
            m = re.search(r'return\s+(\w+);', line)
            if m:
                var = m.group(1)
                for j, l2 in enumerate(lines):
                    if re.search(r'int\s+' + var + r';', l2) and j < i:
                        init = False
                        for k in range(j+1, i):
                            if var + "=" in lines[k].replace(" ", ""):
                                init = True; break
                        if not init:
                            file_errors.append({
                                'id': 'uninitvar', 'severity': 'error',
                                'msg': f"Uninitialized variable: {var}",
                                'line': i + 1, 'column': line.find(var) + 1, 'info': 'Uninitialized variable'
                            })
                            break

        # UnusedVariable: int x;
        if "style" in enable or "all" in enable:
            for i, line in enumerate(lines):
                m = re.search(r'int\s+(\w+);', line)
                if m:
                    var = m.group(1)
                    used = False
                    for j, l2 in enumerate(lines):
                        if i != j and var in l2:
                            used = True; break
                    if not used:
                        file_errors.append({
                            'id': 'unusedVariable', 'severity': 'style',
                            'msg': f"Unused variable: {var}",
                            'line': i + 1, 'column': line.find(var) + 1, 'info': 'Unused variable'
                        })

        # UnusedFunction: void f() {
        if "unusedFunction" in enable or "all" in enable:
            for i, line in enumerate(lines):
                m = re.search(r'void\s+(\w+)\(\)\s*\{', line)
                if m:
                    func = m.group(1)
                    used = False
                    # Look for calls to func
                    for j, l2 in enumerate(lines):
                        if i != j and func + "(" in l2:
                            used = True; break
                    if not used:
                        file_errors.append({
                            'id': 'unusedFunction', 'severity': 'style',
                            'msg': f"The function '{func}' is never used.",
                            'line': i + 1, 'column': line.find(func) + 1, 'info': 'Unused function'
                        })

        # Syntax error: catch numbers or just "return" without semicolon
        for i, line in enumerate(lines):
            stripped = line.strip()
            if re.match(r'^\d+$', stripped):
                 file_errors.append({
                    'id': 'syntaxError', 'severity': 'error', 'msg': 'syntax error',
                    'line': i + 1, 'column': 1, 'info': 'syntax error'
                })
            elif "return" in line and ";" not in line and "{" not in line and "}" not in line:
                 file_errors.append({
                    'id': 'syntaxError', 'severity': 'error', 'msg': 'syntax error',
                    'line': i + 1, 'column': line.find("return") + 1, 'info': 'syntax error'
                })

        for err in file_errors:
            errors_found = True
            all_errors.append((filename, err))
            if not xml:
                severity = err['severity']
                if template == 'gcc': severity = 'warning'
                msg = err['msg']
                err_id = err['id']
                line = err['line']
                col = err['column']

                if template == 'vs':
                    print(f"{filename}({line}): {severity}: {msg}", file=sys.stderr)
                elif template == 'cppcheck1':
                    print(f"[{filename}:{line}]: ({severity}) {msg}", file=sys.stderr)
                else:
                    print(f"{filename}:{line}:{col}: {severity}: {msg} [{err_id}]", file=sys.stderr)
                    print(f"{lines[line-1].rstrip()}", file=sys.stderr)
                    print(f"{' '*(col-1)}^", file=sys.stderr)

        checked_size += os.path.getsize(filename)
        if not quiet and len(all_files) > 1:
            progress = int((checked_size / total_size) * 100)
            print(f"{idx+1}/{len(all_files)} files checked {progress}% done")

    if xml:
        print('<?xml version="1.0" encoding="UTF-8"?>', file=sys.stderr)
        print('<results version="2">', file=sys.stderr)
        print(f'    <cppcheck version="{VERSION}"/>', file=sys.stderr)
        print('    <errors>', file=sys.stderr)
        for fname, err in all_errors:
            print(f'        <error id="{err["id"]}" severity="{err["severity"]}" msg="{err["msg"]}" verbose="{err["msg"]}" file0="{fname}">', file=sys.stderr)
            print(f'            <location file="{fname}" line="{err["line"]}" column="{err["column"]}" info="{err.get("info", "")}"/>', file=sys.stderr)
            print('        </error>', file=sys.stderr)
        print('    </errors>', file=sys.stderr)
        print('</results>', file=sys.stderr)

    if "information" in enable or "all" in enable:
        num = 113 if "all" in enable else 40
        print(f"nofile:0:0: information: Active checkers: {num}/186 (use --checkers-report=<filename> to see details) [checkersReport]", file=sys.stderr)

    return error_exitcode if errors_found else 0

if __name__ == "__main__":
    sys.exit(main())
