./executable --library=cfg/std.cfg test1.c 2>&1
./executable --library=cfg/std.cfg test2.c 2>&1
./executable --library=cfg/std.cfg --enable=all test3.c 2>&1
./executable --library=cfg/std.cfg --xml test1.c 2>&1
"}
